import { useMemo, useState, type CSSProperties } from 'react';

// В @jinx-ui/react нет runtime-примитива календаря (core 8), поэтому разметка собрана на jx-* классах и токенах.

export type ReportDatePickerProps = {
  value?: Date;
  defaultValue?: Date;
  onChange: (date: Date) => void;
  locale?: string;
};

const startOfDay = (d: Date) => new Date(d.getFullYear(), d.getMonth(), d.getDate());
const addDays = (d: Date, n: number) => new Date(d.getFullYear(), d.getMonth(), d.getDate() + n);
const addMonths = (d: Date, n: number) => new Date(d.getFullYear(), d.getMonth() + n, 1);
const isSameDay = (a: Date, b: Date) =>
  a.getFullYear() === b.getFullYear() && a.getMonth() === b.getMonth() && a.getDate() === b.getDate();
const toKey = (d: Date) =>
  `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;

const MONDAY_BASE = new Date(2024, 0, 1);

export default function ReportDatePicker({
  value,
  defaultValue,
  onChange,
  locale = 'ru-RU',
}: ReportDatePickerProps) {
  const today = startOfDay(new Date());
  const [internal, setInternal] = useState<Date>(() => startOfDay(defaultValue ?? value ?? new Date()));
  const selected = value ? startOfDay(value) : internal;
  const [view, setView] = useState<Date>(() => new Date(selected.getFullYear(), selected.getMonth(), 1));

  const weekdays = useMemo(() => {
    const fmt = new Intl.DateTimeFormat(locale, { weekday: 'short' });
    return Array.from({ length: 7 }, (_, i) => fmt.format(addDays(MONDAY_BASE, i)));
  }, [locale]);

  const title = useMemo(
    () => new Intl.DateTimeFormat(locale, { month: 'long', year: 'numeric' }).format(view),
    [locale, view],
  );

  const days = useMemo(() => {
    const first = new Date(view.getFullYear(), view.getMonth(), 1);
    const offset = (first.getDay() + 6) % 7;
    const start = addDays(first, -offset);
    return Array.from({ length: 42 }, (_, i) => addDays(start, i));
  }, [view]);

  const presets: Array<{ label: string; date: Date }> = [
    { label: 'Сегодня', date: today },
    { label: 'Вчера', date: addDays(today, -1) },
    { label: 'Неделя назад', date: addDays(today, -7) },
  ];

  const pick = (date: Date) => {
    const next = startOfDay(date);
    setInternal(next);
    setView(new Date(next.getFullYear(), next.getMonth(), 1));
    onChange(next);
  };

  const rowStyle: CSSProperties = {
    display: 'flex',
    flexWrap: 'wrap',
    gap: 'var(--jx-space-2, 8px)',
    alignItems: 'center',
  };

  const cellStyle = (isSelected: boolean, isToday: boolean, outside: boolean): CSSProperties => ({
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    minHeight: '2.25rem',
    width: '100%',
    borderRadius: 'var(--jx-radius, 4px)',
    border: '1px solid',
    borderColor: isToday ? 'var(--jx-accent, var(--jx-fg, currentColor))' : 'transparent',
    background: isSelected ? 'var(--jx-accent, var(--jx-fg, currentColor))' : 'transparent',
    color: isSelected
      ? 'var(--jx-accent-fg, var(--jx-bg, canvas))'
      : outside
        ? 'var(--jx-muted, currentColor)'
        : 'var(--jx-fg, currentColor)',
    opacity: outside && !isSelected ? 0.5 : 1,
    cursor: 'pointer',
    font: 'inherit',
  });

  return (
    <section
      className="jx-card jx-stack"
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: 'var(--jx-space-3, 12px)',
        padding: 'var(--jx-space-4, 16px)',
        borderRadius: 'var(--jx-radius, 4px)',
        background: 'var(--jx-surface, transparent)',
        color: 'var(--jx-fg, currentColor)',
        maxWidth: '22rem',
      }}
      aria-label="Дата отчёта"
    >
      <div style={rowStyle} role="group" aria-label="Быстрый выбор даты">
        {presets.map((preset) => (
          <button
            key={preset.label}
            type="button"
            className="jx-btn jx-btn--ghost"
            aria-pressed={isSameDay(selected, preset.date)}
            onClick={() => pick(preset.date)}
          >
            {preset.label}
          </button>
        ))}
      </div>

      <div style={{ ...rowStyle, justifyContent: 'space-between', flexWrap: 'nowrap' }}>
        <button
          type="button"
          className="jx-btn jx-btn--ghost"
          aria-label="Предыдущий месяц"
          onClick={() => setView((prev) => addMonths(prev, -1))}
        >
          ‹
        </button>
        <span aria-live="polite" style={{ fontWeight: 600 }}>
          {title}
        </span>
        <button
          type="button"
          className="jx-btn jx-btn--ghost"
          aria-label="Следующий месяц"
          onClick={() => setView((prev) => addMonths(prev, 1))}
        >
          ›
        </button>
      </div>

      <div
        role="grid"
        aria-label={title}
        style={{
          display: 'grid',
          gridTemplateColumns: 'repeat(7, 1fr)',
          gap: 'var(--jx-space-1, 4px)',
        }}
      >
        {weekdays.map((weekday) => (
          <span
            key={weekday}
            role="columnheader"
            style={{
              textAlign: 'center',
              fontSize: 'var(--jx-font-size-sm, 0.85em)',
              color: 'var(--jx-muted, currentColor)',
            }}
          >
            {weekday}
          </span>
        ))}

        {days.map((day) => {
          const outside = day.getMonth() !== view.getMonth();
          const isSelected = isSameDay(day, selected);
          return (
            <button
              key={toKey(day)}
              type="button"
              role="gridcell"
              className="jx-btn jx-btn--ghost"
              aria-selected={isSelected}
              aria-current={isSameDay(day, today) ? 'date' : undefined}
              style={cellStyle(isSelected, isSameDay(day, today), outside)}
              onClick={() => pick(day)}
            >
              {day.getDate()}
            </button>
          );
        })}
      </div>
    </section>
  );
}

